import {chromium} from 'playwright';import {writeFile} from 'node:fs/promises';
const base=process.env.LABNEST_E2E_BASE_URL||'http://localhost:3000',phase=process.env.LABNEST_UI_PHASE||'baseline';const browser=await chromium.launch(),page=await browser.newPage(),checks=[];
for(const width of [1366,1440,390])for(const id of ['master-mix','tm','cfu','dilution','unit-converter','centrifuge']){await page.setViewportSize({width,height:width===1366?768:width===1440?900:844});await page.goto(`${base}/tools/calculator/${id}`);await page.getByRole('button',{name:'Load example',exact:true}).click();await page.getByRole('button',{name:'Calculate',exact:true}).click();await page.evaluate(()=>scrollTo(0,0));checks.push({id,width,...await page.evaluate(()=>{const box=el=>{const r=el?.getBoundingClientRect();return r?{top:r.top,bottom:r.bottom}:null};return{height:innerHeight,scrollHeight:document.documentElement.scrollHeight,calculate:box(document.querySelector('button[type=submit]')),result:box(document.querySelector('[data-calculator-result]')??document.querySelector('.calculator-result-panel')),overflow:document.documentElement.scrollWidth>innerWidth+1}})});}
await writeFile(`docs/calculator/ui-20260915/evidence/measurements-${phase}.json`,JSON.stringify({base,at:new Date().toISOString(),checks},null,2));await browser.close();
